'use strict';
const CACHE='aurea-shell-v23';
const SHELL=['/','/index.html','/styles.css','/icons.js','/app.js','/parity.js','/offline.js','/executive.js','/audit.js','/workflow-policy.js','/workflows.js','/pos-profit-policy.js','/pos-profit.js','/crm.js','/crm-commerce.js','/crm-followups.js','/crm-campaigns.js','/crm-communications.js','/charles-full.js','/pagination.js'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('aurea-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||url.pathname.startsWith('/api/'))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok&&SHELL.includes(url.pathname)){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy)).catch(()=>{});}return response;}).catch(()=>caches.match(event.request).then(response=>response||(event.request.mode==='navigate'?caches.match('/index.html'):Response.error()))));});
